let LINGUA = 'it';
function t(k, p) {
  let s = (TESTI[LINGUA] && TESTI[LINGUA][k]) ?? TESTI.it[k] ?? k;
  if (p) for (const x in p) s = s.split('{' + x + '}').join(p[x]);
  return s;
}
/* testi fissi della pagina: data-t (testo), data-th (html), data-tp (placeholder), data-tt (title) */
function traduciPagina() {
  document.documentElement.lang = LINGUA;
  document.querySelectorAll('[data-t]').forEach(e => { e.textContent = t(e.dataset.t); });
  document.querySelectorAll('[data-th]').forEach(e => { e.innerHTML = t(e.dataset.th); });
  document.querySelectorAll('[data-tp]').forEach(e => { e.placeholder = t(e.dataset.tp); });
}
